use crate::tools::{ToolRuntime, tool_definitions};
use anyhow::{Context, Result, bail};
use reqwest::blocking::{Client, Response};
use serde::Serialize;
use serde_json::{Value, json};
use std::io::{BufRead, BufReader};
use std::path::PathBuf;
use std::sync::mpsc::Sender;
use std::time::Duration;

const MAX_AGENT_TURNS: usize = 20;

#[derive(Debug, Clone)]
pub struct AgentConfig {
    pub base_url: String,
    pub api_key: String,
    pub model: String,
    pub route: String,
    pub workspace: PathBuf,
}

#[derive(Debug)]
pub enum AgentEvent {
    Activity(String),
    ApprovalRequested {
        description: String,
        response: Sender<bool>,
    },
    ToolFinished {
        name: String,
        summary: String,
        success: bool,
    },
    ResponseStarted,
    ResponseDelta(String),
}

#[derive(Debug)]
pub struct AgentSummary {
    pub model: String,
    pub route: String,
}

pub fn run_agent(
    config: AgentConfig,
    prompt: String,
    mut emit: impl FnMut(AgentEvent) -> bool,
) -> Result<AgentSummary> {
    let runtime = ToolRuntime::new(config.workspace.clone())?;
    let client = Client::builder()
        .timeout(Duration::from_secs(180))
        .build()
        .context("failed to create LiteLLM client")?;
    let endpoint = chat_completions_endpoint(&config.base_url);
    let mut messages = vec![
        json!({
            "role": "system",
            "content": system_prompt(runtime.root().display().to_string())
        }),
        json!({ "role": "user", "content": prompt }),
    ];

    for _ in 0..MAX_AGENT_TURNS {
        if !emit(AgentEvent::Activity(format!(
            "Asking {} via {}",
            config.model, config.route
        ))) {
            bail!("task cancelled");
        }
        let turn = request_turn(&client, &endpoint, &config, &messages, &mut emit)?;
        messages.push(turn.as_message());

        if turn.tool_calls.is_empty() {
            if turn.content.trim().is_empty() {
                bail!("LiteLLM returned an empty response");
            }
            return Ok(AgentSummary {
                model: config.model,
                route: config.route,
            });
        }

        for tool_call in turn.tool_calls {
            let description = ToolRuntime::approval_description(
                &tool_call.function.name,
                &tool_call.function.arguments,
            );
            if !emit(AgentEvent::Activity(description.clone())) {
                bail!("task cancelled");
            }

            let approved = if ToolRuntime::requires_approval(&tool_call.function.name) {
                request_approval(&description, &mut emit)?
            } else {
                true
            };
            let result = if approved {
                runtime.execute(&tool_call.function.name, &tool_call.function.arguments)
            } else {
                Err(anyhow::anyhow!("user denied this tool call"))
            };

            let (content, summary, success) = match result {
                Ok(output) => (output.content, output.summary, output.success),
                Err(error) => {
                    let message = format!("Tool error: {error:#}");
                    (message.clone(), message, false)
                }
            };
            if !emit(AgentEvent::ToolFinished {
                name: tool_call.function.name.clone(),
                summary,
                success,
            }) {
                bail!("task cancelled");
            }
            messages.push(json!({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "name": tool_call.function.name,
                "content": content
            }));
        }
    }

    bail!("agent stopped after {MAX_AGENT_TURNS} turns")
}

fn request_turn(
    client: &Client,
    endpoint: &str,
    config: &AgentConfig,
    messages: &[Value],
    emit: &mut impl FnMut(AgentEvent) -> bool,
) -> Result<AssistantTurn> {
    let response = client
        .post(endpoint)
        .bearer_auth(&config.api_key)
        .json(&json!({
            "model": config.model,
            "messages": messages,
            "tools": tool_definitions(),
            "tool_choice": "auto",
            "stream": true,
            "metadata": {
                "shiprr_route": config.route,
                "shiprr_client": "shipr-cli"
            }
        }))
        .send()
        .context("failed to reach LiteLLM")?;
    parse_streaming_response(response, emit)
}

fn parse_streaming_response(
    response: Response,
    emit: &mut impl FnMut(AgentEvent) -> bool,
) -> Result<AssistantTurn> {
    let status = response.status();
    if !status.is_success() {
        let body = response.text().unwrap_or_default();
        bail!("LiteLLM returned {status}: {body}");
    }

    let reader = BufReader::new(response);
    let mut content = String::new();
    let mut response_started = false;
    let mut tool_calls: Vec<ToolCallBuilder> = Vec::new();

    for line in reader.lines() {
        let line = line.context("failed while reading LiteLLM stream")?;
        let Some(data) = line.strip_prefix("data:") else {
            continue;
        };
        let data = data.trim();
        if data == "[DONE]" {
            break;
        }
        let event: Value = serde_json::from_str(data).context("invalid LiteLLM stream event")?;
        if let Some(error) = event.get("error") {
            bail!("LiteLLM stream error: {error}");
        }
        let Some(delta) = event
            .get("choices")
            .and_then(Value::as_array)
            .and_then(|choices| choices.first())
            .and_then(|choice| choice.get("delta"))
        else {
            continue;
        };

        if let Some(fragment) = delta.get("content").and_then(Value::as_str) {
            if !response_started {
                if !emit(AgentEvent::ResponseStarted) {
                    bail!("task cancelled");
                }
                response_started = true;
            }
            content.push_str(fragment);
            if !emit(AgentEvent::ResponseDelta(fragment.to_string())) {
                bail!("task cancelled");
            }
        }

        if let Some(fragments) = delta.get("tool_calls").and_then(Value::as_array) {
            for fragment in fragments {
                accumulate_tool_call(&mut tool_calls, fragment)?;
            }
        }
    }

    let tool_calls = tool_calls
        .into_iter()
        .map(ToolCallBuilder::finish)
        .collect::<Result<Vec<_>>>()?;
    Ok(AssistantTurn {
        content,
        tool_calls,
    })
}

fn accumulate_tool_call(tool_calls: &mut Vec<ToolCallBuilder>, fragment: &Value) -> Result<()> {
    let index = fragment
        .get("index")
        .and_then(Value::as_u64)
        .context("tool call stream fragment omitted index")? as usize;
    while tool_calls.len() <= index {
        tool_calls.push(ToolCallBuilder::default());
    }
    let builder = &mut tool_calls[index];
    if let Some(id) = fragment.get("id").and_then(Value::as_str) {
        builder.id.push_str(id);
    }
    if let Some(function) = fragment.get("function") {
        if let Some(name) = function.get("name").and_then(Value::as_str) {
            builder.name.push_str(name);
        }
        if let Some(arguments) = function.get("arguments").and_then(Value::as_str) {
            builder.arguments.push_str(arguments);
        }
    }
    Ok(())
}

fn request_approval(description: &str, emit: &mut impl FnMut(AgentEvent) -> bool) -> Result<bool> {
    let (sender, receiver) = std::sync::mpsc::channel();
    if !emit(AgentEvent::ApprovalRequested {
        description: description.to_string(),
        response: sender,
    }) {
        return Ok(false);
    }
    receiver.recv().context("approval prompt closed")
}

fn system_prompt(workspace: String) -> String {
    format!(
        "You are Shiprr, a minimal coding agent operating in {workspace}. \
Use tools to inspect the repository before changing it. Make focused edits that solve the user's task. \
All file paths must be relative to the workspace. Prefer replace_in_file for small edits and write_file for new files. \
Run relevant checks after editing. Never claim a file or command changed unless the matching tool succeeded. \
When the task is complete, respond with a concise summary and validation results."
    )
}

fn chat_completions_endpoint(base_url: &str) -> String {
    let base = base_url.trim_end_matches('/');
    if base.ends_with("/v1") {
        format!("{base}/chat/completions")
    } else {
        format!("{base}/v1/chat/completions")
    }
}

#[derive(Debug)]
struct AssistantTurn {
    content: String,
    tool_calls: Vec<ToolCall>,
}

impl AssistantTurn {
    fn as_message(&self) -> Value {
        json!({
            "role": "assistant",
            "content": if self.content.is_empty() { Value::Null } else { Value::String(self.content.clone()) },
            "tool_calls": self.tool_calls
        })
    }
}

#[derive(Debug, Clone, Serialize)]
struct ToolCall {
    id: String,
    #[serde(rename = "type")]
    kind: &'static str,
    function: FunctionCall,
}

#[derive(Debug, Clone, Serialize)]
struct FunctionCall {
    name: String,
    arguments: String,
}

#[derive(Debug, Default)]
struct ToolCallBuilder {
    id: String,
    name: String,
    arguments: String,
}

impl ToolCallBuilder {
    fn finish(self) -> Result<ToolCall> {
        if self.id.is_empty() || self.name.is_empty() {
            bail!("LiteLLM returned an incomplete tool call");
        }
        Ok(ToolCall {
            id: self.id,
            kind: "function",
            function: FunctionCall {
                name: self.name,
                arguments: self.arguments,
            },
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{Read, Write};
    use std::net::TcpListener;
    use std::thread;
    use tempfile::tempdir;

    #[test]
    fn appends_v1_for_plain_gateway_urls() {
        assert_eq!(
            chat_completions_endpoint("http://localhost:4000/"),
            "http://localhost:4000/v1/chat/completions"
        );
    }

    #[test]
    fn preserves_existing_v1_prefix() {
        assert_eq!(
            chat_completions_endpoint("http://localhost:4000/v1"),
            "http://localhost:4000/v1/chat/completions"
        );
    }

    #[test]
    fn combines_streamed_tool_call_fragments() {
        let mut calls = Vec::new();
        accumulate_tool_call(
            &mut calls,
            &json!({ "index": 0, "id": "call_1", "function": { "name": "write_", "arguments": "{\"pa" } }),
        )
        .expect("first fragment");
        accumulate_tool_call(
            &mut calls,
            &json!({ "index": 0, "function": { "name": "file", "arguments": "th\":\"x\"}" } }),
        )
        .expect("second fragment");

        let call = calls.pop().expect("tool call").finish().expect("complete");
        assert_eq!(call.function.name, "write_file");
        assert_eq!(call.function.arguments, r#"{"path":"x"}"#);
    }

    #[test]
    fn runs_an_approved_file_tool_then_streams_the_answer() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("mock gateway");
        let address = listener.local_addr().expect("gateway address");
        let server = thread::spawn(move || {
            serve_sse(
                &listener,
                &[
                    json!({
                        "choices": [{
                            "delta": {
                                "tool_calls": [{
                                    "index": 0,
                                    "id": "call_1",
                                    "function": {
                                        "name": "write_file",
                                        "arguments": "{\"path\":\"created.txt\","
                                    }
                                }]
                            }
                        }]
                    }),
                    json!({
                        "choices": [{
                            "delta": {
                                "tool_calls": [{
                                    "index": 0,
                                    "function": { "arguments": "\"content\":\"hello\"}" }
                                }]
                            }
                        }]
                    }),
                ],
            );
            serve_sse(
                &listener,
                &[
                    json!({ "choices": [{ "delta": { "content": "Created " } }] }),
                    json!({ "choices": [{ "delta": { "content": "the file." } }] }),
                ],
            );
        });
        let workspace = tempdir().expect("workspace");
        let mut streamed = String::new();
        let mut tool_succeeded = false;

        run_agent(
            AgentConfig {
                base_url: format!("http://{address}"),
                api_key: "test-key".to_string(),
                model: "test-model".to_string(),
                route: "test-route".to_string(),
                workspace: workspace.path().to_path_buf(),
            },
            "create a file".to_string(),
            |event| {
                match event {
                    AgentEvent::ApprovalRequested { response, .. } => {
                        response.send(true).expect("approve tool");
                    }
                    AgentEvent::ToolFinished { success, .. } => tool_succeeded = success,
                    AgentEvent::ResponseDelta(delta) => streamed.push_str(&delta),
                    _ => {}
                }
                true
            },
        )
        .expect("agent run");
        server.join().expect("mock gateway thread");

        assert!(tool_succeeded);
        assert_eq!(streamed, "Created the file.");
        assert_eq!(
            std::fs::read_to_string(workspace.path().join("created.txt")).expect("created file"),
            "hello"
        );
    }

    fn serve_sse(listener: &TcpListener, events: &[Value]) {
        let (mut stream, _) = listener.accept().expect("gateway request");
        let mut request = [0_u8; 16_384];
        let _ = stream.read(&mut request).expect("read request");
        let body = events
            .iter()
            .map(|event| format!("data: {event}\n\n"))
            .collect::<String>()
            + "data: [DONE]\n\n";
        write!(
            stream,
            "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            body.len(),
            body
        )
        .expect("write response");
    }
}

use anyhow::{Context, Result, bail};
use serde::Deserialize;
use serde_json::{Value, json};
use std::fs;
use std::path::{Component, Path, PathBuf};
use std::process::Command;

const MAX_TOOL_OUTPUT_BYTES: usize = 32_000;
const SKIPPED_DIRECTORIES: [&str; 4] = [".git", "target", "node_modules", ".venv"];

#[derive(Debug)]
pub struct ToolRuntime {
    root: PathBuf,
}

#[derive(Debug)]
pub struct ToolOutput {
    pub content: String,
    pub summary: String,
    pub success: bool,
}

impl ToolRuntime {
    pub fn new(root: PathBuf) -> Result<Self> {
        let root = root
            .canonicalize()
            .with_context(|| format!("failed to open workspace {}", root.display()))?;
        Ok(Self { root })
    }

    pub fn root(&self) -> &Path {
        &self.root
    }

    pub fn requires_approval(name: &str) -> bool {
        matches!(name, "write_file" | "replace_in_file" | "run_command")
    }

    pub fn approval_description(name: &str, arguments: &str) -> String {
        let parsed: Value = serde_json::from_str(arguments).unwrap_or(Value::Null);
        match name {
            "write_file" => format!(
                "write {}",
                parsed["path"].as_str().unwrap_or("the requested file")
            ),
            "replace_in_file" => format!(
                "edit {}",
                parsed["path"].as_str().unwrap_or("the requested file")
            ),
            "run_command" => {
                let program = parsed["program"].as_str().unwrap_or("command");
                let args = parsed["args"]
                    .as_array()
                    .map(|items| {
                        items
                            .iter()
                            .filter_map(Value::as_str)
                            .collect::<Vec<_>>()
                            .join(" ")
                    })
                    .unwrap_or_default();
                format!("run {program} {args}").trim().to_string()
            }
            _ => format!("use {name}"),
        }
    }

    pub fn execute(&self, name: &str, arguments: &str) -> Result<ToolOutput> {
        match name {
            "list_files" => self.list_files(parse_arguments(arguments)?),
            "read_file" => self.read_file(parse_arguments(arguments)?),
            "search" => self.search(parse_arguments(arguments)?),
            "write_file" => self.write_file(parse_arguments(arguments)?),
            "replace_in_file" => self.replace_in_file(parse_arguments(arguments)?),
            "run_command" => self.run_command(parse_arguments(arguments)?),
            _ => bail!("unknown tool: {name}"),
        }
    }

    fn list_files(&self, arguments: ListFilesArguments) -> Result<ToolOutput> {
        let relative_path = arguments.path.unwrap_or_else(|| ".".to_string());
        let path = self.resolve_existing_path(&relative_path)?;
        if !path.is_dir() {
            bail!("{} is not a directory", relative_path);
        }

        let mut files = Vec::new();
        collect_files(&self.root, &path, &mut files)?;
        files.sort();
        let total = files.len();
        files.truncate(arguments.limit.unwrap_or(300).min(1_000));
        let content = truncate_output(files.join("\n"));
        Ok(ToolOutput {
            content,
            summary: format!("listed {total} files under {relative_path}"),
            success: true,
        })
    }

    fn read_file(&self, arguments: ReadFileArguments) -> Result<ToolOutput> {
        let path = self.resolve_existing_path(&arguments.path)?;
        if !path.is_file() {
            bail!("{} is not a file", arguments.path);
        }

        let content = fs::read_to_string(&path)
            .with_context(|| format!("failed to read {}", arguments.path))?;
        let lines: Vec<&str> = content.lines().collect();
        let start = arguments.start_line.unwrap_or(1).max(1);
        let end = arguments.end_line.unwrap_or(lines.len()).min(lines.len());
        if start > end.saturating_add(1) {
            bail!("start_line must be before end_line");
        }

        let selected = lines
            .iter()
            .enumerate()
            .filter(|(index, _)| {
                let line_number = index + 1;
                line_number >= start && line_number <= end
            })
            .map(|(index, line)| format!("{:>5} | {line}", index + 1))
            .collect::<Vec<_>>()
            .join("\n");
        Ok(ToolOutput {
            content: truncate_output(selected),
            summary: format!("read {} lines {start}-{end}", arguments.path),
            success: true,
        })
    }

    fn search(&self, arguments: SearchArguments) -> Result<ToolOutput> {
        let relative_path = arguments.path.unwrap_or_else(|| ".".to_string());
        let path = self.resolve_existing_path(&relative_path)?;
        let output = Command::new("rg")
            .args(["-n", "--hidden", "--glob", "!.git", "--glob", "!target"])
            .arg("--")
            .arg(&arguments.query)
            .arg(&path)
            .current_dir(&self.root)
            .output()
            .context("failed to run rg; install ripgrep to use search")?;

        let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
        let stderr = String::from_utf8_lossy(&output.stderr);
        if !output.status.success() && output.status.code() != Some(1) {
            bail!("search failed: {}", stderr.trim());
        }

        let matches = stdout.lines().count();
        Ok(ToolOutput {
            content: if stdout.is_empty() {
                "No matches found.".to_string()
            } else {
                truncate_output(stdout)
            },
            summary: format!("found {matches} matches for {:?}", arguments.query),
            success: true,
        })
    }

    fn write_file(&self, arguments: WriteFileArguments) -> Result<ToolOutput> {
        let path = self.resolve_writable_path(&arguments.path)?;
        let parent = path.parent().context("file path has no parent")?;
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create directory {}", parent.display()))?;
        self.ensure_inside_workspace(parent)?;
        fs::write(&path, arguments.content.as_bytes())
            .with_context(|| format!("failed to write {}", arguments.path))?;
        Ok(ToolOutput {
            content: format!(
                "Wrote {} bytes to {}.",
                arguments.content.len(),
                arguments.path
            ),
            summary: format!("wrote {}", arguments.path),
            success: true,
        })
    }

    fn replace_in_file(&self, arguments: ReplaceInFileArguments) -> Result<ToolOutput> {
        if arguments.old_text.is_empty() {
            bail!("old_text cannot be empty");
        }
        let path = self.resolve_existing_path(&arguments.path)?;
        let content = fs::read_to_string(&path)
            .with_context(|| format!("failed to read {}", arguments.path))?;
        let occurrences = content.matches(&arguments.old_text).count();
        if occurrences != 1 {
            bail!("old_text must match exactly once; found {occurrences} matches");
        }
        let updated = content.replacen(&arguments.old_text, &arguments.new_text, 1);
        fs::write(&path, updated)
            .with_context(|| format!("failed to update {}", arguments.path))?;
        Ok(ToolOutput {
            content: format!("Updated {}.", arguments.path),
            summary: format!("edited {}", arguments.path),
            success: true,
        })
    }

    fn run_command(&self, arguments: RunCommandArguments) -> Result<ToolOutput> {
        if arguments.program.trim().is_empty() {
            bail!("program cannot be empty");
        }
        let output = Command::new(&arguments.program)
            .args(&arguments.args)
            .current_dir(&self.root)
            .output()
            .with_context(|| format!("failed to run {}", arguments.program))?;

        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        let combined = format!(
            "$ {} {}\n{}{}",
            arguments.program,
            arguments.args.join(" "),
            stdout,
            stderr
        );
        let exit_code = output.status.code().unwrap_or(-1);
        Ok(ToolOutput {
            content: truncate_output(combined),
            summary: format!("{} exited with {exit_code}", arguments.program),
            success: output.status.success(),
        })
    }

    fn resolve_existing_path(&self, relative_path: &str) -> Result<PathBuf> {
        let candidate = self.resolve_lexical_path(relative_path)?;
        let canonical = candidate
            .canonicalize()
            .with_context(|| format!("path does not exist: {relative_path}"))?;
        self.ensure_inside_workspace(&canonical)?;
        Ok(canonical)
    }

    fn resolve_writable_path(&self, relative_path: &str) -> Result<PathBuf> {
        let candidate = self.resolve_lexical_path(relative_path)?;
        if candidate.exists() {
            self.ensure_inside_workspace(&candidate.canonicalize()?)?;
        } else if let Some(existing_ancestor) = candidate.ancestors().find(|path| path.exists()) {
            self.ensure_inside_workspace(&existing_ancestor.canonicalize()?)?;
        }
        Ok(candidate)
    }

    fn resolve_lexical_path(&self, relative_path: &str) -> Result<PathBuf> {
        let path = Path::new(relative_path);
        if relative_path.trim().is_empty() || path.is_absolute() {
            bail!("tool paths must be relative to the workspace");
        }
        for component in path.components() {
            match component {
                Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
                    bail!("path cannot leave the workspace")
                }
                Component::Normal(name) if name == ".git" => {
                    bail!("editing .git is not allowed")
                }
                _ => {}
            }
        }
        Ok(self.root.join(path))
    }

    fn ensure_inside_workspace(&self, path: &Path) -> Result<()> {
        if !path.starts_with(&self.root) {
            bail!("path cannot leave workspace {}", self.root.display());
        }
        Ok(())
    }
}

pub fn tool_definitions() -> Vec<Value> {
    vec![
        tool_definition(
            "list_files",
            "List files in the workspace. Build artifacts and dependency directories are skipped.",
            json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "Relative directory, defaults to ." },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 1000 }
                }
            }),
        ),
        tool_definition(
            "read_file",
            "Read a UTF-8 text file with line numbers.",
            json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string" },
                    "start_line": { "type": "integer", "minimum": 1 },
                    "end_line": { "type": "integer", "minimum": 1 }
                },
                "required": ["path"]
            }),
        ),
        tool_definition(
            "search",
            "Search workspace text with ripgrep.",
            json!({
                "type": "object",
                "properties": {
                    "query": { "type": "string" },
                    "path": { "type": "string", "description": "Relative file or directory, defaults to ." }
                },
                "required": ["query"]
            }),
        ),
        tool_definition(
            "write_file",
            "Create or overwrite a UTF-8 file. Requires user approval.",
            json!({
                "type": "object",
                "properties": {
                    "path": { "type": "string" },
                    "content": { "type": "string" }
                },
