#[derive(Parser, Debug)]
#[command(
    name = "shipr",
    version,
    about = "Shiprr — minimal cargo agent with smart low-cost routing",
    long_about = "A lightweight CLI harness for coding tasks.\nRuns a focused plan -> work -> verify loop and uses harness-level smart routing to reduce cost."
)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand, Debug)]
enum Commands {
    Start,
    Login,
    Run {
        #[arg(help = "Coding task to execute")]
        task: String,
        #[arg(long, value_enum)]
        quality: Option<Quality>,
        #[arg(long, value_enum)]
        budget: Option<Budget>,
    },
    Plan {
        #[arg(help = "Task to plan")]
        task: String,
    },
    Preview,
}

#[derive(Debug)]
struct ShiprrConfig {
    base_url: String,
    api_key: String,
    model: String,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        None => launch_tui(),
        Some(Commands::Start) => start_setup(false),
        Some(Commands::Login) => start_setup(true),
        Some(Commands::Run {
            task,
            quality,
            budget,
        }) => run_once(task, quality, budget),
        Some(Commands::Plan { task }) => show_plan(&task),
        Some(Commands::Preview) => preview_branding(),
    }
}

fn launch_tui() -> Result<()> {
    let config = ensure_config()?;
    tui::run(tui::TuiConfig {
        base_url: config.base_url,
        api_key: [REDACTED],
        model: config.model,
        workspace: std::env::current_dir().context("failed to open current workspace")?,
    })
}

fn ensure_config() -> Result<ShiprrConfig> {
    if let Some(config) = load_config()? {
        return Ok(config);
    }

    start_setup(false)?;
    load_config()?.context("failed to load config after setup")
}

fn start_setup(force_login: bool) -> Result<()> {
    print_shiprr_banner();

    if !force_login && let Some(config) = load_config()? {
        println!(
            "{} {}",
            "Already logged in:".truecolor(147, 197, 253),
            config.base_url.bright_white()
        );
        println!(
            "{} {}",
            "config:".truecolor(147, 197, 253),
            config_path().display().to_string().bright_white()
        );
        println!(
            "{} {}",
            "model:".truecolor(147, 197, 253),
            config.model.bright_white()
        );
        return Ok(());
    }

    println!();
    println!("{}", "Login to LiteLLM".bold().bright_white());

    let base_url: String = Input::new()
        .with_prompt("LiteLLM base URL")
        .default("http://localhost:4000".to_string())
        .interact_text()
        .context("failed to read base URL input")?;

    let api_key = [REDACTED]
        .with_prompt("LiteLLM API key")
        .allow_empty_password(false)
        .interact()
        .context("failed to read API key input")?;

    let model: String = Input::new()
        .with_prompt("LiteLLM model or auto-router alias")
        .default("auto_router1".to_string())
        .interact_text()
        .context("failed to read model input")?;

    let config = ShiprrConfig {
        base_url,
        api_key,
        model,
    };
    validate_config(&config)?;
    save_config(&config)?;

    println!(
        "{}",
        "Login saved. Run shipr to start coding.".truecolor(147, 197, 253)
    );
    Ok(())
}

fn run_once(
    task: String,
    quality_override: Option<Quality>,
    budget_override: Option<Budget>,
) -> Result<()> {
    let Some(config) = load_config()? else {
        bail!("not signed in. Run shipr start first.");
    };
    let routing = resolve_routing_policy(&task, quality_override, budget_override);
    let model = select_model(&routing.policy);

    println!();
    println!("{} {}", "Task".bold().bright_white(), task.bright_white());
    println!(
        "{} {} ({}, est {})",
        "Route".truecolor(147, 197, 253),
        model.name.bright_white(),
        model.rationale,
        model.estimated_cost
    );
    println!(
        "{} {} via {}",
        "Status".truecolor(147, 197, 253),
        "ready for execution".bright_white(),
        config.base_url
    );
    Ok(())
}

